param([Parameter(Mandatory)][int]$Cycle,[Parameter(Mandatory)][int]$PostgresPort,[Parameter(Mandatory)][int]$ApplicationPort,[Parameter(Mandatory)][string]$EvidenceRoot)
$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $PSCommandPath);$fixture=Join-Path $root 'fixture';$project="rawsql-v05-qualification-$Cycle-$PostgresPort";New-Item -ItemType Directory -Force -Path (Join-Path $EvidenceRoot 'qualification')|Out-Null;$out=Join-Path $EvidenceRoot "qualification/cycle-$Cycle.json";$scratch=Join-Path ([System.IO.Path]::GetTempPath()) ("rawsql-v05-qualification-"+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $scratch|Out-Null;$app=$null;$probe=$null
$checks=[ordered]@{postgresImageRuntime=$false;canonicalDdl=$false;seed=$false;nodeDependencies=$false;typescriptBuild=$false;neutralAppStart=$false;healthEndpoint=$false;representativeDbAccess=$false;evaluatorStartup=$false;productionPublishPath=$false;cleanTeardown=$false;portReleased=$false;noBenchmarkLeaks=$false};$evaluatorResult=$null
function Stop-Descendants([int]$ParentProcessId) {foreach($child in @(Get-CimInstance Win32_Process -Filter "ParentProcessId=$ParentProcessId" -ErrorAction SilentlyContinue)){Stop-Descendants ([int]$child.ProcessId);Stop-Process -Id $child.ProcessId -Force -ErrorAction SilentlyContinue}}
function Invoke-ComposeCommand([string[]]$ComposeArguments,[int]$TimeoutSeconds=30) {
 $arguments=@('compose','-p',$project,'-f',(Join-Path $fixture 'compose.yaml'))+$ComposeArguments;$commandLine=(($arguments|ForEach-Object{if($_ -match '\s'){'"'+$_+'"'}else{$_}})-join ' ');$stdout=Join-Path $scratch ("docker-"+[guid]::NewGuid().ToString('N')+".out.log");$stderr=Join-Path $scratch ("docker-"+[guid]::NewGuid().ToString('N')+".err.log");$process=Start-Process -FilePath docker.exe -ArgumentList $commandLine -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru
 if(-not $process.WaitForExit($TimeoutSeconds*1000)){Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue;throw "docker compose command timed out for $project"};return $process.ExitCode
}
function Invoke-ComposeText([string[]]$ComposeArguments,[int]$TimeoutSeconds=30) {
 $arguments=@('compose','-p',$project,'-f',(Join-Path $fixture 'compose.yaml'))+$ComposeArguments;$commandLine=(($arguments|ForEach-Object{if($_ -match '\s'){'"'+$_+'"'}else{$_}})-join ' ');$stdout=Join-Path $scratch ("docker-"+[guid]::NewGuid().ToString('N')+".out.log");$stderr=Join-Path $scratch ("docker-"+[guid]::NewGuid().ToString('N')+".err.log");$process=Start-Process -FilePath docker.exe -ArgumentList $commandLine -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru
 if(-not $process.WaitForExit($TimeoutSeconds*1000)){Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue;throw "docker compose command timed out for $project"};if($process.ExitCode -ne 0){throw "docker compose command failed for $project"};$text=Get-Content -Raw $stdout;return ([string]$text).Trim()
}
function Stop-ComposeProject {if((Invoke-ComposeCommand -ComposeArguments @('down','--timeout','15','--volumes','--remove-orphans')) -ne 0){throw "docker compose teardown failed: $project"}}
try{
 $env:POSTGRES_PORT=$PostgresPort;if((Invoke-ComposeCommand -ComposeArguments @('up','-d')) -ne 0){throw 'docker compose up'}
 foreach($n in 1..30){if((Invoke-ComposeCommand -ComposeArguments @('exec','-T','postgres','pg_isready','-U','postgres','-d','inventory') -TimeoutSeconds 10) -eq 0){$checks.postgresImageRuntime=$true;break};Start-Sleep 1};if(-not $checks.postgresImageRuntime){throw 'postgres readiness'}
 $count=Invoke-ComposeText -ComposeArguments @('exec','-T','postgres','psql','-U','postgres','-d','inventory','-At','-c','select count(*) from inventory_items');if($count -ne '4'){throw 'canonical ddl or seed'};$checks.canonicalDdl=$true;$checks.seed=$true
 npm ci --ignore-scripts --silent --prefix $fixture;if($LASTEXITCODE -ne 0){throw 'npm ci'};$checks.nodeDependencies=$true;npm run build --silent --prefix $fixture;if($LASTEXITCODE -ne 0){throw 'tsc'};$checks.typescriptBuild=$true
 $env:DATABASE_URL="postgres://postgres:postgres@127.0.0.1:$PostgresPort/inventory";$env:PORT=$ApplicationPort;$app=Start-Process npm.cmd -ArgumentList @('start','--silent') -WorkingDirectory $fixture -RedirectStandardOutput (Join-Path $scratch 'app.out.log') -RedirectStandardError (Join-Path $scratch 'app.err.log') -PassThru
 foreach($n in 1..30){try{if((Invoke-WebRequest "http://127.0.0.1:$ApplicationPort/health" -SkipHttpErrorCheck).StatusCode-eq200){$checks.neutralAppStart=$true;$checks.healthEndpoint=$true;$checks.productionPublishPath=$true;break}}catch{};Start-Sleep 1};if(-not$checks.healthEndpoint){throw 'health'}
 if((Invoke-ComposeText -ComposeArguments @('exec','-T','postgres','psql','-U','postgres','-d','inventory','-At','-c','select 1')) -ne '1'){throw 'representative db'};$checks.representativeDbAccess=$true
 $probe=Join-Path $fixture '.rawsql-v05-qualification-evaluate.mjs';Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'evaluate.mjs') -Destination $probe -Force;& node --check $probe;if($LASTEXITCODE -ne 0){throw 'evaluator syntax'};Push-Location $fixture;try{$evaluatorOutput=& node -e "require.resolve('pg');console.log('pg-resolved')"}finally{Pop-Location};$evaluatorResult=[ordered]@{mode='syntax-and-dependency-resolution';output=($evaluatorOutput|Select-Object -Last 1)};if($LASTEXITCODE -ne 0 -or $evaluatorResult.output -ne 'pg-resolved'){throw 'evaluator dependency resolution'};$checks.evaluatorStartup=$true
}catch{$err=$_.Exception.Message}finally{if($app){Stop-Descendants ([int]$app.Id);if(-not $app.HasExited){Stop-Process -Id $app.Id -Force -ErrorAction SilentlyContinue}};if($probe-and(Test-Path $probe)){Remove-Item -LiteralPath $probe -Force -ErrorAction SilentlyContinue};try{Stop-ComposeProject;$checks.cleanTeardown=$true}catch{if(-not $err){$err=$_.Exception.Message}};Start-Sleep -Milliseconds 300;$checks.portReleased=-not(Get-NetTCPConnection -LocalPort $PostgresPort -State Listen -ErrorAction SilentlyContinue);$checks.noBenchmarkLeaks=$checks.portReleased;$result=[ordered]@{cycle=$Cycle;checks=$checks;evaluator=$evaluatorResult;pass=($checks.Values -notcontains $false);error=$err};$result|ConvertTo-Json -Depth 6|Set-Content $out;Remove-Item -LiteralPath $scratch -Recurse -Force -ErrorAction SilentlyContinue;if(-not $result.pass){exit 1}}
